/**
 * SMS config + delivery types — Sawaa Dashboard
 *
 * Every RESPONSE shape is derived from the committed OpenAPI snapshot
 * (`lib/types/api.generated.ts`, regenerated by `pnpm openapi:sync`), so a
 * backend response change becomes a type error here instead of drifting
 * silently. `test/unit/lib/comms-type-contract.spec.ts` pins that.
 *
 * Credentials are write-only: the GET/POST view carries only the boolean
 * `credentialsConfigured`, never `credentialsCiphertext` or `webhookSecret`.
 */

import type { components } from "@/lib/types/api.generated"

type Schemas = components["schemas"]

/* ─── Entities (derived from OpenAPI) ─── */

/** Provider vocabulary of `OrganizationSmsConfig.provider`. */
export type SmsProvider = Schemas["SmsSettingsResponseDto"]["provider"]

/** Provider delivery-state vocabulary (`SmsDeliveryStatus`). */
export type SmsDeliveryStatus = Schemas["SmsDeliveryResponseDto"]["status"]

/** The whole SMS settings view; the settings form is the only reader. */
export type SmsConfigView = Schemas["SmsSettingsResponseDto"]

/** Unifonic block inside the upsert body. */
export type UnifonicCredentialsInput = NonNullable<Schemas["UpsertOrgSmsConfigDto"]["unifonic"]>

/** Taqnyat block inside the upsert body. */
export type TaqnyatCredentialsInput = NonNullable<Schemas["UpsertOrgSmsConfigDto"]["taqnyat"]>

/** `POST /dashboard/comms/settings/sms` body. */
export type UpsertSmsConfigInput = Schemas["UpsertOrgSmsConfigDto"]

/** `POST /dashboard/comms/settings/sms/test` result. */
export type TestSmsResult = Schemas["SmsSettingsTestResultDto"]

/** One row of the 50 most recent deliveries, exactly as the handler projects it. */
export type SmsDeliveryRow = Schemas["SmsDeliveryResponseDto"]
